CREATE OR REPLACE FUNCTION public.x_public_landing(p_id text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$ declare p public.x_landing_pages; prod public.x_products; store_name text; begin select * into p from public.x_landing_pages where id=p_id and active; if not found then raise exception 'الصفحة غير متوفرة'; end if; select * into prod from public.x_products where id=p.product_id and active; if not found then raise exception 'المنتج غير متوفر'; end if; select coalesce(nullif(trim(data->>'pageName'),''),'المتجر') into store_name from public.x_profiles where user_id=p.merchant_id; return jsonb_build_object('id',p.id,'storeName',coalesce(store_name,'المتجر'),'product',prod.data||jsonb_build_object('id',prod.id,'stock',prod.stock),'sale',p.sale,'freeDelivery',p.free_delivery,'deliveryCost',(select data->'deliveryCost' from public.x_settings where id)); end $function$;